class OrganicMountainRangesTest{public static void main(String[]a){double r=.14,aspect=2;long seed=71;double asymmetry=0;int peaks=0;double last=0,current=0;for(int i=0;i<=1000;i++){double u=-1+i*.002;double center=OrganicMountainRanges.spine(u,seed),next=OrganicMountainRanges.profile(u*r*aspect,center*r,r,aspect,.5,seed);if(i>1&&current>last&&current>next)peaks++;last=current;current=next;asymmetry+=Math.abs(OrganicMountainRanges.profile(u*r*aspect,.35*r,r,aspect,.5,seed)-OrganicMountainRanges.profile(u*r*aspect,-.35*r,r,aspect,.5,seed));}double variation=0;for(int i=1;i<100;i++)variation+=Math.abs(OrganicMountainRanges.spine(i/100.,seed)-OrganicMountainRanges.spine((i-1)/100.,seed));double nearEdge=OrganicMountainRanges.profile(0,1.4*r,r,aspect,.5,seed);if(peaks<3||asymmetry<1||variation<.05||nearEdge!=0)throw new AssertionError("Range is regular or has a hard outer edge: "+peaks+" "+asymmetry+" "+variation+" "+nearEdge);double e=1e-4;if(OrganicMountainRanges.fade(e)>1e-9||OrganicMountainRanges.fade(1-e)<1-1e-9)throw new AssertionError("Foothill fade does not flatten at both ends");System.out.println("PASS: curved spine, asymmetric branches, multiple irregular summits and a foothill envelope that flattens at its boundary");}}
